'use strict';
const teaching=ClassCastTeaching,editHistory=new teaching.History();let historyApplying=false,historyProject=null,batchCandidate=null,batchSource='';
function historyButtons(){$('undoEdit').disabled=busy()||editHistory.index<=0;$('redoEdit').disabled=busy()||editHistory.index>=editHistory.items.length-1}
const teachingDirty=dirty;dirty=function(){teachingDirty();if(!historyApplying&&loaded&&sourceBlob){if(historyProject!==projectId){historyProject=projectId;editHistory.reset(snapshot())}else editHistory.push(snapshot())}historyButtons()};
function resetHistory(){historyProject=projectId;editHistory.reset(loaded?snapshot():null);historyButtons();batchCandidate=null;$('applyBatch').disabled=true;$('batchPreview').textContent=''}
const teachingLoad=loadVideo;loadVideo=async function(...args){const ok=await teachingLoad(...args);if(ok){resetHistory();$('privacyStart').value=0;$('privacyEnd').value=duration.toFixed(2)}return ok};
const teachingImport=$('projectFile').onchange;$('projectFile').onchange=async e=>{const before=projectId;await teachingImport(e);if(projectId!==before)resetHistory()};
const teachingRestore=restoreProject;restoreProject=async function(...args){await teachingRestore(...args);resetHistory()};
function applyHistory(state){if(!state)return;stopPreview();historyApplying=true;try{clips=state.clips;subs=state.subs;marks=state.marks;pendingMark=null;cursorTrail=null;applySettings(state.settings);$('exportName').value=state.name;$('projectName').textContent=state.name;renderLists();draw()}finally{historyApplying=false;historyButtons()}}
$('undoEdit').onclick=()=>{if(allowEdit())applyHistory(editHistory.undo())};$('redoEdit').onclick=()=>{if(allowEdit())applyHistory(editHistory.redo())};
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey||e.target.closest('input,textarea,[contenteditable="true"]'))return;const key=e.key.toLowerCase();if(key==='z'||key==='y'){e.preventDefault();if(key==='y'||e.shiftKey)$('redoEdit').click();else $('undoEdit').click()}});
new MutationObserver(historyButtons).observe(document.body,{attributes:true,attributeFilter:['class']});
function reviewBatch(next){batchCandidate=next;batchSource=JSON.stringify(subs);let changed=0;for(let i=0;i<Math.max(next.length,subs.length);i++)if(JSON.stringify(next[i])!==JSON.stringify(subs[i]))changed++;$('batchPreview').textContent=`將調整 ${changed} 段，調整後共 ${next.length} 段（移除 ${Math.max(0,subs.length-next.length)} 段）。\n`+next.slice(0,8).map(s=>`${s.start.toFixed(2)}–${s.end.toFixed(2)}  ${s.text}`).join('\n');$('applyBatch').disabled=!changed}
$('previewReplace').onclick=()=>{if(!allowEdit())return;try{reviewBatch(teaching.replaceSubtitles(subs,$('batchFind').value,$('batchReplace').value))}catch(e){notify(e.message)}};
$('previewShift').onclick=()=>{if(!allowEdit())return;try{reviewBatch(teaching.shiftSubtitles(subs,Number($('batchOffset').value),duration))}catch(e){notify(e.message)}};
$('applyBatch').onclick=()=>{if(!allowEdit()||!batchCandidate)return;if(batchSource!==JSON.stringify(subs))return notify('字幕已改變，請重新預覽批次校正。');subs=batchCandidate;batchCandidate=null;renderLists();$('applyBatch').disabled=true;$('batchPreview').textContent='已套用，可使用復原還原。'};
for(const id of ['batchFind','batchReplace','batchOffset'])$(id).addEventListener('input',()=>{batchCandidate=null;$('applyBatch').disabled=true});
$('privacyTool').onclick=()=>{if(!allowEdit())return;$('drawTool').value='mosaic';applyCursor();notify('請在影片畫面拖曳框選要遮住的區域。')};
canvas.addEventListener('pointerdown',()=>{if(pendingMark?.tool==='mosaic'){const start=Number($('privacyStart').value),end=Number($('privacyEnd').value);if(recorder||!validRange(start,end)){pendingMark=null;notify('請於錄影完成後設定有效的遮罩起迄時間。');return}Object.assign(pendingMark,{start,end:Math.min(end,duration),animated:false,privacyMode:$('privacyMode').value,pixelSize:Number($('privacySize').value)})}});
const teachingFinishMark=finishMark;finishMark=function(){if(pendingMark?.tool==='mosaic'){if(pendingMark.points.length<2||Math.abs(pendingMark.points.at(-1).x-pendingMark.points[0].x)<.003||Math.abs(pendingMark.points.at(-1).y-pendingMark.points[0].y)<.003){pendingMark=null;return}pendingMark.end=Math.min(duration,Number($('privacyEnd').value))}teachingFinishMark()};
// Existing listeners hold the old function reference; replace them explicitly.
canvas.removeEventListener('pointerup',teachingFinishMark);canvas.removeEventListener('pointercancel',teachingFinishMark);canvas.addEventListener('pointerup',finishMark);canvas.addEventListener('pointercancel',finishMark);
const originalPaintMark=paintMark;paintMark=function(m,t){if(m.tool==='mosaic')ClassCastRenderer(canvas,{settings:readSettings(),subs:[],marks:[]}).privacy(m,t);else originalPaintMark(m,t)};
draw=function(){if(!loaded)return;const state={settings:readSettings(),subs,marks};ClassCastRenderer(canvas,state).render(video,video.currentTime);if(pendingMark)paintMark(pendingMark,video.currentTime);if(cursorTrail)paintMark(cursorTrail,video.currentTime);if(!exporting&&cursorPoint&&$('cursorEnabled').checked)paintCursor(cursorPoint.x*canvas.width,cursorPoint.y*canvas.height,$('cursorShape').value,$('cursorColor').value,numberSetting('cursorSize',12,72)*canvas.width/1280)};
$('closeRecovery').onclick=()=>$('recoveryDialog').close();
async function showRecovery(){const list=$('recoveryList');list.textContent='正在讀取…';try{const rows=await ClassCastRecovery.list();list.replaceChildren();if(!rows.length)list.textContent='目前沒有錄影備份。';for(const row of rows){const el=document.createElement('div');el.className='item';const label=document.createElement('span');label.className='text';label.textContent=`${row.name} · 已保存 ${clock(row.seconds)} · ${(row.bytes/1048576).toFixed(1)} MB${row.complete?' · 已結束':' · 中斷或仍錄製中'}`;const open=document.createElement('button');open.textContent='恢復編輯';open.disabled=!row.count;open.onclick=async()=>{if(busy())return notify('請先完成目前作業。');window.projectBusy=true;try{const blob=await ClassCastRecovery.blob(row);window.projectBusy=false;if(await loadVideo(blob,row.name,row.seconds)){restoreLiveAnnotations(row.marks||[]);await saveProject(false);resetHistory();$('recoveryDialog').close()}}catch(e){notify(e.message)}finally{window.projectBusy=false}};const save=document.createElement('button');save.textContent='下載原始備份';save.disabled=!row.count;save.onclick=async()=>{try{download(await ClassCastRecovery.blob(row),row.name.replace(/[/:]/g,'-')+(row.mime.includes('mp4')?'.mp4':'.webm'))}catch(e){notify(e.message)}};const remove=document.createElement('button');remove.textContent='刪除備份';remove.onclick=async()=>{if(busy())return notify('請先完成目前作業。');if(!confirm('永久刪除此錄影救援備份？請先確認已儲存專案或下載影片。'))return;try{await ClassCastRecovery.remove(row.id);await showRecovery()}catch(e){notify(e.message)}};el.append(label,open,save,remove);list.append(el)}}catch(e){list.textContent='無法讀取備份：'+e.message}}
$('recoveryBtn').onclick=()=>{$('recoveryDialog').showModal();showRecovery()};
ClassCastRecovery.list().then(rows=>{if(rows.some(r=>r.count&&!r.complete))$('recoveryStatus').textContent='發現中斷的錄影，請點「錄影救援」恢復已保存內容。'}).catch(()=>{$('recoveryStatus').textContent='本機錄影備份無法使用，開始錄影時會提示。'});
